add('13_001',3,'16:9，从青后侧的中全景迅速向上摇，起幅保留她向前推完、两腿分开、发束向后扬的姿态，跟上断烟囱的旋转轨迹，落在断烟囱居中、武士位于远处左上的纵深构图。','青后脚蹬开，腰胯向武士方向送出，右掌把断烟囱猛推离身；掌根与砖面分离后，右臂顺势伸到前方，后肩与长发被反作用拉向身后。断烟囱带着空腔和整片砖面旋转前飞，越过青身前的尘浪，直砸远处武士；她仍保持掌推完成后的大开步姿态。','近侧灰褐屋面斜铺，米灰尘浪从脚旁摊开；上摇时屋面退出，米灰断烟囱与深褐开口映在铅蓝天空上。','烟囱后方开阔天空冷白漫射，旋转块体的明暗面随转动交替。','蹬地闷响与掌推的短促发力声，随后沉重块体旋转裂风、近处砂粒炸散。',japanese=['そんな口をきくなんて！'],tone='把前句情绪顶上来，推出时重读，句尾不拖。',phase='process',kind='mixed',node={'青.接触':'右掌已离开断烟囱','烟囱.状态':'向武士旋转前飞','青.阶段':'掌推完成'},meaning='用户确认手掌前推砸出断烟囱；近景右侧青与远处武士、旋转砖体的构图保留，不写抓取后投掷。',pcard={'opening':'青的掌根已压实，准备把羞恼化成反击。','beats':['脚蹬与腰胯前送同时推出','掌根离面，发束与肩背反向拉开'],'coupling':'语言重音落在掌推发力而非额外动作。','landing':'烟囱离手前飞，青保留推完后的势。'},update={'first_pass':{'viewed':True,'resolution':'720p','session_date':'2026-10-25','observation':'青在画面右下两腿分开、身体转向前方，长发向后扬，单臂伸出；断烟囱有开口并旋转飞向远处左上武士。','initial_action_understanding':'按用户明确解释为掌推砸出断烟囱后的完成姿态。'}})
add('13_002',4,'16:9，武士握柄手、胸口与围布的横幅特写；右手居中，刀鞘斜穿画面左侧，眼睛在上缘外；固定到握紧后沿刀柄外拉半个手掌宽。','武士的拇指在护手旁一压，右手重新扣紧刀柄，护手和鞘口之间露出亮缝；围布随一口鼻息轻轻鼓起，右腕将刀身向外抽，掌背与前臂结成一条明确斩线，动作毫无迟疑。','围布与衣襟间露出极窄浅冷灰空隙，右后方细密斜向线条沿烟囱来向压入。','同一开阔天空冷白柔光，出鞘缝出现短而硬的刀面反光。','握柄皮布轻响、鼻息和一声利落出鞘擦音，块体低风声继续逼近。',japanese=['ふん。','動きがあまりにも読みやすい。'],tone='内心笃定，第一声短，后句冷静。',phase='preparation',kind='mixed',node={'武士.刀':'右手再次拔刀','武士.阶段':'判断断烟囱来路'},pcard={'opening':'武士注意力在迎来的断烟囱，自以为已看穿。','beats':['鼻息，拇指推护手','扣柄抽刀毫不犹豫'],'coupling':'自信使反击直接而快，为后续视野受阻埋下节奏。','landing':'刀已经起动切向来物。'})
add('13_003',.5,'16:9，满幅黑底与白色交错刀路，固定构图；粗线由画面侧缘斜穿，细线与其错向相交。','第一道粗白斩线突然贯穿黑底，随后数道细线错向闪过，交汇处短促扩亮；最后一道斜线掠出，黑底收回，只留将接碎石的运动方向。','纯黑图形底场，粗细不同的白色锐线交错，非实体光束。','非实景图形处理，白线是短促视觉重音。','数记紧贴的锐利切风，与下一镜最初一声石裂相接。',phase='process',node={'武士.刀':'右手连续切开断烟囱'},meaning='原作的交错白线图形节点保留，表现多道快速刀路，不新增光束能力。',background_mode='graphic')
